  "claims": [
    {
      "claim": "The query is warfarin, a low-MW acidic 4-hydroxycoumarin; no supplied record directly measures warfarin F, but L1 direct F records for small acidic drugs ketoprofen (≥92%, ~90%, >0.9) and suprofen (92.2%) support F≥20% for this class.",
      "card_ids": ["C15","C18","C19","C16"]
    },
    {
      "claim": "L4 C47 reports that related 4-hydroxycoumarin anticoagulants ethylbiscoumacetate and acenocoumarol are mostly well absorbed in humans, while dicoumarol is less predictable; this qualitative absorption evidence is the closest structural-class support.",
      "card_ids": ["C47"]
    },
    {
      "claim": "L4 ketoprofen records report human fraction absorbed 90-100% (C46, C49, C52, C53, C54, C48, C50, C51), consistent with good oral absorption of small acidic drugs.",
      "card_ids": ["C46","C49","C52","C53","C54","C48","C50","C51"]
    },
    {
      "claim": "L5 gut-wall/efflux records are not warfarin-specific; several show high Caco-2 permeability and no significant efflux (C62, C61/C57, C65, C63, C58, C55/C66), and none provides affirmative evidence of F<20%.",
      "card_ids": ["C62","C61","C57","C65","C63","C58","C55","C66"]
    },
    {
      "claim": "L5 C56/C60 show a modest BL-AP/AP-BL ratio (~1.37) for free WED but with high absolute Papp (~20×10^-6 cm/s); this is not warfarin-specific and does not constitute affirmative F<20% evidence.",
      "card_ids": ["C56","C60"]
    },
    {
      "claim": "Low non-human values C24 (ketoprofen quail 24%) and C29 (levothyroxine dogs 22%) are at/above the 20% threshold and species-specific; they do not support F<20%.",
      "card_ids": ["C24","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C55","C56","C57","C58","C59","C60","C61","C62","C63","C64","C65","C66"]
    }
  ],
  "evidence_gaps": [
    "No direct warfarin-specific absolute oral bioavailability or IV-comparator record is supplied.",
    "L5 records are mostly flavones, ferulic-acid derivatives, AFN-1252, WED, or ketoprofen; none measures warfarin gut-wall efflux or intestinal metabolism.",
    "No intestinal metabolism record was supplied in the L5 bundle.",
    "C47 is qualitative ('well absorbed') and does not include warfarin itself.",
    "Transfer from ketoprofen/suprofen to warfarin is structural-class inference, not direct."
  ],
  "decision_summary": "Predicted high: warfarin is a low-MW acidic 4-hydroxycoumarin; L1 high-F records for small acidic drugs (ketoprofen, suprofen), L4 absorption records including related 4-hydroxycoumarin anticoagulants, and the absence of any affirmative F<20% evidence support F≥20%. L5 adds no warfarin-specific gut-wall/efflux or intestinal-metabolism result and does not change the decision. Confidence remains moderate because no direct warfarin-specific F record is available."
}

